package main

import (
	"bytes"
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// TestUpgradeContractResources: on a real app (gombit new, make resource),
// gombit upgrade contract checks the generator-owned resource files the way
// gombit generate --check does: current as scaffolded, stale once one
// differs from what the framework renders, regenerated by --write. The
// human-owned hooks file and frontend pages are never written. While the
// resources are stale or just regenerated, the running app's document (an
// app built from them) is unchecked, and --write does not write it.
func TestUpgradeContractResources(t *testing.T) {
	if testing.Short() {
		t.Skip("scaffolds and compiles an app")
	}
	workDir := t.TempDir()
	chdir(t, workDir)
	if err := run(context.Background(), []string{"new", "demo", "--database", "sqlite", "--skip-tidy"}, ioDiscard{}, ioDiscard{}); err != nil {
		t.Fatalf("gombit new: %v", err)
	}
	dest := filepath.Join(workDir, "demo")
	appendReplace(t, dest)
	tidy := exec.Command("go", "mod", "tidy")
	tidy.Dir = dest
	if out, err := tidy.CombinedOutput(); err != nil {
		t.Fatalf("go mod tidy: %v\n%s", err, out)
	}
	chdir(t, dest)
	if err := run(context.Background(), []string{"make", "resource", "Book", "title:string:required", "--skip-migrations"}, ioDiscard{}, ioDiscard{}); err != nil {
		t.Fatalf("make resource: %v", err)
	}
	contractRun := func(args ...string) (string, error) {
		var out bytes.Buffer
		err := run(context.Background(), append([]string{"upgrade", "contract", "--dir", dest}, args...), &out, ioDiscard{})
		return out.String(), err
	}

	out, err := contractRun()
	if err != nil || !strings.Contains(out, "resources: current") {
		t.Fatalf("as scaffolded: %v\n%s", err, out)
	}

	dto := filepath.Join(dest, "internal", "book", "dto.gen.go")
	hooks := filepath.Join(dest, "internal", "book", "hooks.go")
	generated := readFileString(t, dto)
	myHooks := readFileString(t, hooks) + "\n// my own hook notes\n"
	writeFile := func(path, content string) {
		t.Helper()
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil { // #nosec G703 -- under t.TempDir()
			t.Fatal(err)
		}
	}
	writeFile(dto, generated+"\n// drifted\n")
	writeFile(hooks, myHooks)
	// Every handwritten frontend file (all of frontend/src but the
	// generated client).
	before := map[string]string{}
	src := filepath.Join(dest, "frontend", "src")
	_ = filepath.WalkDir(src, func(p string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			if d != nil && d.IsDir() && p == filepath.Join(src, "api", "generated") {
				return filepath.SkipDir
			}
			return err
		}
		before[p] = readFileString(t, p)
		return nil
	})
	if len(before) < 5 {
		t.Fatalf("found %d frontend files; the walk is wrong", len(before))
	}

	out, err = contractRun()
	if err == nil || !strings.Contains(out, "resources: stale: internal/book/dto.gen.go") || !strings.Contains(out, "regenerate: gombit generate") {
		t.Fatalf("after a drift: %v\n%s", err, out)
	}
	// The running app (served here) was built from the stale resources.
	committedSpec := `{"openapi":"3.1.0","info":{"title":"committed","version":"1"}}`
	writeFile(filepath.Join(dest, "openapi.json"), committedSpec)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"openapi":"3.1.0","info":{"title":"live","version":"1"}}`))
	}))
	defer srv.Close()
	out, err = contractRun("--url", srv.URL+"/openapi.json")
	if err == nil || !strings.Contains(out, "openapi:  unchecked: the resource files are stale") {
		t.Fatalf("stale resources with --url: %v\n%s", err, out)
	}
	out, err = contractRun("--write", "--url", srv.URL+"/openapi.json")
	if err != nil || !strings.Contains(out, "resources: written: internal/book/dto.gen.go") || !strings.Contains(out, "openapi:  unchecked: the resource files were just regenerated") {
		t.Fatalf("--write: %v\n%s", err, out)
	}
	if readFileString(t, filepath.Join(dest, "openapi.json")) != committedSpec {
		t.Fatal("--write wrote the document of an app built from the stale resources")
	}
	// A failure after the resources are written (here, openapi-typescript
	// fails checking the client) names what was written.
	if falseBin, err := exec.LookPath("false"); err == nil {
		writeFile(dto, generated+"\n// drifted again\n")
		_, err := contractRun("--write", "--npx", falseBin)
		if err == nil || !strings.Contains(err.Error(), "the resources were regenerated first: internal/book/dto.gen.go") {
			t.Fatalf("a failure after the resource write: %v", err)
		}
		if readFileString(t, dto) != generated {
			t.Fatal("dto.gen.go was not regenerated before the failure")
		}
	}
	if err := os.Remove(filepath.Join(dest, "openapi.json")); err != nil { // gombit new commits none
		t.Fatal(err)
	}
	if readFileString(t, dto) != generated {
		t.Fatal("--write did not regenerate dto.gen.go")
	}
	if readFileString(t, hooks) != myHooks {
		t.Fatal("--write changed the human-owned hooks.go")
	}
	for p, content := range before {
		if readFileString(t, p) != content {
			t.Fatalf("--write changed the handwritten frontend file %s", p)
		}
	}
	if out, err := contractRun(); err != nil || !strings.Contains(out, "resources: current") {
		t.Fatalf("second check: %v\n%s", err, out)
	}
	// Hooks declared in another file: current, and --write seeds no
	// hooks.go beside them (that would redeclare Hooks).
	if err := os.Rename(hooks, filepath.Join(dest, "internal", "book", "myhooks.go")); err != nil {
		t.Fatal(err)
	}
	if out, err := contractRun("--write"); err != nil || !strings.Contains(out, "resources: current") {
		t.Fatalf("--write with hooks in another file: %v\n%s", err, out)
	}
	if _, err := os.Stat(hooks); !os.IsNotExist(err) {
		t.Fatalf("--write seeded hooks.go (%v)", err)
	}
}
